import React, { useEffect, useRef } from "react"
import { Link } from "gatsby"
import { motion } from "framer-motion"
import { ArrowDown, ArrowUpRight } from "lucide-react"
import * as styles from "./hero.module.css"

const Hero = () => {
  const blobRef = useRef(null)
  const imgRef = useRef(null)

  useEffect(() => {
    const onScroll = () => {
      if (blobRef.current) {
        blobRef.current.style.transform = `translateY(${window.scrollY * 0.25}px)`
      }
      if (imgRef.current) {
        imgRef.current.style.transform = `translateY(${window.scrollY * 0.12}px)`
      }
    }
    window.addEventListener("scroll", onScroll, { passive: true })
    return () => window.removeEventListener("scroll", onScroll)
  }, [])

  return (
    <section className={styles.hero}>
      <div ref={blobRef} className={styles.blob} aria-hidden="true" />
      <div className={styles.gradientOrb} aria-hidden="true" />
      <div className={styles.gridBg} aria-hidden="true" />

      <div className="container">
        <div className={styles.wrapper}>
          <div className={styles.main}>
            <div className={styles.badge}>
              <span className={styles.dot} />
              Senior Frontend Developer
            </div>

            <h1 className={styles.nameText}>
              Rahul Tailor
            </h1>

            <h2 className={styles.title}>
              Crafting digital experiences with{" "}
              <span className={styles.accent}>precision</span>
            </h2>

            <div className={styles.meta}>
              <p className={styles.intro}>
                I create impactful digital solutions by merging intuitive UI/UX,
                modern frontend technologies, and AI-driven enhancements.
              </p>

              <div className={styles.actions}>
                <Link to="/work/" className="btn btn-primary">
                  View my work <ArrowUpRight size={18} />
                </Link>
                <Link to="/contact/" className="btn btn-ghost">
                  Let&apos;s Talk
                </Link>
              </div>
            </div>
          </div>

          <div className={styles.profileCol}>
            <div className={styles.profileWrap} ref={imgRef}>
              <div className={styles.profileGlow} aria-hidden="true" />
              <div className={styles.profileRing} aria-hidden="true" />
              <img
                src="/images/profile.svg"
                alt="Rahul Tailor"
                className={styles.profileImg}
              />
              <div className={styles.expBadge}>
                <span className={styles.expNum}>6+</span>
                <span className={styles.expLabel}>Years Exp.</span>
              </div>
            </div>
          </div>
        </div>

        <div className={styles.scroll}>
          <ArrowDown size={16} />
          <span>Scroll to explore</span>
        </div>
      </div>
    </section>
  )
}

export default Hero
